 select count(*) into problems from (
  select 1 from baseline b left join versus_private.localized_dictionary d using(word_language,theme_key,word_key)
   where d.word is distinct from b.word
  union all
  select 1 from versus_private.localized_dictionary d left join (select * from baseline union all select * from additions) e using(word_language,theme_key,word_key)
   where e.word is distinct from d.word
  union all
  select 1 from additions a where public.versus_letter_key(a.word)<>a.word_key
 ) mismatch;
 if problems<>0 then raise exception 'Dictionary baseline/normalizer mismatch (% entries). Stop; no changes applied.',problems;end if;
end $baseline$;
